index 77b0c66..8aa30d0 100644
--- a/sistema/sistema.cpp
+++ b/sistema/sistema.cpp
@@ -1853,6 +1853,146 @@ void process_dump(des_proc* p, log_sev sev)


 // ( SOLUZIONE 2025-06-05
+
+/*! @brief Parte C++ della primitiva swap_out().
+ *  @param pid		processo da rimuovere
+ *  @param buf		buffer per il contenuto della pila utente
+ */
+extern "C" bool c_swap_out(natl pid, char *buf)
+{
+	// Trojan horse check: buf must be accessible and writable from user level
+	if (!c_access(int_cast<vaddr>(buf), DIM_USR_STACK, true, false)) {
+		flog(LOG_WARN, "swap_out: parametri non validi");
+		c_abort_p();
+		return false;
+	}
+
+	// Check pid validity
+	if (pid >= MAX_PROC) {
+		flog(LOG_WARN, "swap_out: pid non valido %u", pid);
+		c_abort_p();
+		return false;
+	}
+
+	// Check if process exists
+	if (proc_table[pid] == nullptr) {
+		esecuzione->contesto[I_RAX] = false;
+		return false;
+	}
+
+	des_proc* p = proc_table[pid];
+
+	// Error: system process
+	if (p->livello != LIV_UTENTE) {
+		flog(LOG_WARN, "swap_out: processo di sistema %u", pid);
+		c_abort_p();
+		return false;
+	}
+
+	// Error: current process
+	if (p == esecuzione) {
+		flog(LOG_WARN, "swap_out: tentativo di rimuovere se stessi");
+		c_abort_p();
+		return false;
+	}
+
+	// Return false if already swapped out
+	if (p->swapped_out) {
+		esecuzione->contesto[I_RAX] = false;
+		return false;
+	}
+
+	// Copy user stack content to buffer.
+	// The user stack occupies [fin_utn_p - DIM_USR_STACK, fin_utn_p).
+	vaddr stack_start = fin_utn_p - DIM_USR_STACK;
+	for (natq i = 0; i < DIM_USR_STACK; i++) {
+		paddr pa = trasforma(p->cr3, stack_start + i);
+		if (pa)
+			buf[i] = *reinterpret_cast<const char*>(static_cast<vaddr>(pa));
+		else
+			buf[i] = 0;
+	}
+
+	// Deallocate user stack frames and mappings
+	distruggi_pila(p->cr3, fin_utn_p, DIM_USR_STACK);
+
+	p->swapped_out = true;
+	p->scheduled = false;
+
+	esecuzione->contesto[I_RAX] = true;
+	return true;
+}
+
+/*! @brief Parte C++ della primitiva swap_in().
+ *  @param pid		processo da ricaricare
+ *  @param buf		buffer contenente i dati per la pila utente
+ */
+extern "C" bool c_swap_in(natl pid, const char *buf)
+{
+	// Trojan horse check: buf must be accessible and readable from user level
+	if (!c_access(int_cast<vaddr>(buf), DIM_USR_STACK, false, false)) {
+		flog(LOG_WARN, "swap_in: parametri non validi");
+		c_abort_p();
+		return false;
+	}
+
+	// Check pid validity
+	if (pid >= MAX_PROC) {
+		flog(LOG_WARN, "swap_in: pid non valido %u", pid);
+		c_abort_p();
+		return false;
+	}
+
+	// Check if process exists
+	if (proc_table[pid] == nullptr) {
+		esecuzione->contesto[I_RAX] = false;
+		return false;
+	}
+
+	des_proc* p = proc_table[pid];
+
+	// Error: system process
+	if (p->livello != LIV_UTENTE) {
+		flog(LOG_WARN, "swap_in: processo di sistema %u", pid);
+		c_abort_p();
+		return false;
+	}
+
+	// Return false if not swapped out
+	if (!p->swapped_out) {
+		esecuzione->contesto[I_RAX] = false;
+		return false;
+	}
+
+	// Recreate user stack
+	if (!crea_pila(p->cr3, fin_utn_p, DIM_USR_STACK, LIV_UTENTE)) {
+		flog(LOG_WARN, "swap_in: creazione pila utente fallita per proc %u", pid);
+		esecuzione->contesto[I_RAX] = false;
+		return false;
+	}
+
+	// Copy buffer content to user stack
+	vaddr stack_start = fin_utn_p - DIM_USR_STACK;
+	for (natq i = 0; i < DIM_USR_STACK; i++) {
+		paddr pa = trasforma(p->cr3, stack_start + i);
+		if (pa)
+			*reinterpret_cast<char*>(static_cast<vaddr>(pa)) = buf[i];
+	}
+
+	p->swapped_out = false;
+
+	// If process was scheduled while removed, re-insert into ready queue
+	// respecting priority, and clear the scheduled flag
+	if (p->scheduled) {
+		p->scheduled = false;
+		inspronti();
+		inserimento_lista(pronti, p);
+		schedulatore();
+	}
+
+	esecuzione->contesto[I_RAX] = true;
+	return true;
+}
 //   SOLUZIONE 2025-06-05 )


